+  let bannerTimer = 0, resetTimer = 0, dashCooldown = 0, soundOn = true, audioCtx = null;
+  let particles = [];
+  const player = { x: 290, y: 300, vx: 0, vy: 0, faceX: 1, faceY: 0, r: 19, dash: 0 };
+  const rival = { x: 710, y: 300, vx: 0, vy: 0, faceX: -1, faceY: 0, r: 19, kickWait: 0, dash: 0 };
+  const ball = { x: 500, y: 300, vx: 0, vy: 0, r: 11, spin: 0, trail: [] };
+  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
+  const norm = (x, y) => { const m = Math.hypot(x, y) || 1; return [x / m, y / m]; };
+
+  function resize() {
+    const rect = canvas.getBoundingClientRect();
+    const dpr = Math.min(window.devicePixelRatio || 1, 2);
+    canvas.width = Math.round(rect.width * dpr);
+    canvas.height = Math.round(rect.height * dpr);
+    ctx.setTransform(canvas.width / W, 0, 0, canvas.height / H, 0, 0);
+  }
+  window.addEventListener('resize', resize);
+  new ResizeObserver(resize).observe(canvas);
+  resize();
+
+  function tone(freq, duration, type = 'sine', volume = .035) {
+    if (!soundOn) return;
+    try {
+      audioCtx ||= new (window.AudioContext || window.webkitAudioContext)();
+      const osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
+      osc.type = type; osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
+      gain.gain.setValueAtTime(volume, audioCtx.currentTime);
+      gain.gain.exponentialRampToValueAtTime(.001, audioCtx.currentTime + duration);
+      osc.connect(gain); gain.connect(audioCtx.destination); osc.start(); osc.stop(audioCtx.currentTime + duration);
+    } catch (_) {}
+  }
+  function updateHud() {
+    $('youScore').textContent = youScore;
+    $('aiScore').textContent = aiScore;
+    $('clock').textContent = overtime ? 'GOLDEN' : `${String(Math.floor(matchTime / 60)).padStart(2, '0')}:${String(Math.ceil(matchTime % 60)).padStart(2, '0')}`;
+    $('period').textContent = overtime ? 'SUDDEN DEATH' : matchTime <= 45 ? 'SECOND HALF' : 'FIRST HALF';
+    $('progressText').textContent = `${Math.min(goals, 3)} / 3`;
+    $('progress').style.width = `${Math.min(goals / 3, 1) * 100}%`;
+    if (goals >= 3) { $('missionTitle').textContent = 'Contract complete'; $('missionText').textContent = 'Three goals. The street league knows your name.'; }
+  }
+  function resetPositions() {
+    player.x = 290; player.y = 300; player.vx = player.vy = 0; player.faceX = 1; player.faceY = 0;
+    rival.x = 710; rival.y = 300; rival.vx = rival.vy = 0; rival.faceX = -1; rival.faceY = 0; rival.kickWait = .5;
+    ball.x = 500; ball.y = 300; ball.vx = ball.vy = 0; ball.trail.length = 0; charge = 0;
+  }
+  function showBanner(text) {
+    $('banner').textContent = text;
+    $('banner').classList.add('show'); bannerTimer = 1.25;
+  }
