+    $('primaryBtn').textContent = kind === 'ready' ? 'KICK OFF' : kind === 'paused' ? 'RESUME MATCH' : 'PLAY AGAIN';
+    $('modalHint').textContent = kind === 'ready' ? 'WASD / ARROWS TO MOVE · HOLD SPACE TO CHARGE YOUR SHOT' : kind === 'paused' ? 'PRESS P TO RESUME · YOUR MATCH IS ON HOLD' : 'A NEW MATCH IS WAITING FOR YOU';
