+      $('modalEyebrow').textContent = 'A new season starts now';
+      $('modalTitle').innerHTML = 'OWN THE<br><em>FIELD.</em>';
+      $('modalText').textContent = 'One pitch. One rival. Make your move and prove you belong in the street league.';
+    } else if (kind === 'paused') {
+      $('modalEyebrow').textContent = 'Halftime? Not quite.';
+      $('modalTitle').innerHTML = 'TAKE A<br><em>BREATHER.</em>';
+      $('modalText').textContent = `The score is ${youScore}–${aiScore}. Catch your breath, then get back out there.`;
+    } else {
+      const won = youScore > aiScore;
+      $('modalEyebrow').textContent = won ? 'Contract secured' : youScore === aiScore ? 'A hard-fought draw' : 'The league awaits your comeback';
+      $('modalTitle').innerHTML = won ? 'AGENT<br><em>OF THE DAY.</em>' : youScore === aiScore ? 'EVENLY<br><em>MATCHED.</em>' : 'BACK TO<br><em>TRAINING.</em>';
+      $('modalText').textContent = `Full time: ${youScore}–${aiScore}. ${won ? 'That pitch is yours.' : youScore === aiScore ? 'One more match could settle it.' : 'Every great agent starts somewhere.'}`;
+    }
+  }
+  function startMatch() {
+    if (mode === 'ready' || mode === 'finished') {
+      youScore = 0; aiScore = 0; matchTime = 90; overtime = false;
+      if (mode === 'finished') goals = 0;
+      $('missionTitle').textContent = 'Find the net';
+      $('missionText').textContent = 'Score 3 goals to complete your first agent contract.';
+      updateHud(); resetPositions();
+    }
+    mode = 'playing'; $('overlay').classList.add('hidden'); lastTime = performance.now();
+    tone(540, .12, 'triangle');
+  }
+  $('primaryBtn').addEventListener('click', startMatch);
+  $('pauseBtn').addEventListener('click', () => {
