document.querySelectorAll('.touch-btn').forEach((btn) => {
  const key = btn.dataset.key;
  const down = (e) => { e.preventDefault(); btn.classList.add('pressed'); btn.setPointerCapture?.(e.pointerId); press(key); };
  const up = (e) => { e.preventDefault(); btn.classList.remove('pressed'); release(key); };
  btn.addEventListener('pointerdown', down); btn.addEventListener('pointerup', up); btn.addEventListener('pointercancel', up); btn.addEventListener('lostpointercapture', up);
});

function kickSound(power) { tone(170 + power * 120, .12, 'triangle', .06); }
function shootPlayer() {
  const dist = Math.hypot(ball.x - player.x, ball.y - player.y);
  if (dist > 73) return;
  const power = clamp(.28 + (performance.now() - chargeAt) / 1150, .35, 1);
  const towardGoal = norm(952 - ball.x, 300 - ball.y);
  let dx = player.faceX * .68 + towardGoal[0] * .32;
  let dy = player.faceY * .68 + towardGoal[1] * .32;
  [dx, dy] = norm(dx, dy);
  ball.vx = dx * (430 + power * 400); ball.vy = dy * (430 + power * 400);
  ball.x += dx * 8; ball.y += dy * 8;
  charge = 0; kickSound(power); burst(ball.x, ball.y, '#eaffaa', 6);
}
function shootRival() {
  const direction = norm(-952, 300 - ball.y + (Math.random() - .5) * 55);
  const power = .74 + Math.random() * .2;
  ball.vx = direction[0] * (515 + power * 240); ball.vy = direction[1] * (515 + power * 240);
  ball.x += direction[0] * 8; ball.y += direction[1] * 8;
  rival.kickWait = 1.15 + Math.random() * .55;
  tone(155, .1, 'triangle', .035); burst(ball.x, ball.y, '#ffb2a1', 5);
}
function burst(x, y, color, count) {
  for (let i = 0; i < count; i++) {
    const a = Math.random() * Math.PI * 2, speed = 35 + Math.random() * 145;
    particles.push({x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:.25+Math.random()*.38,max:.63,color,size:2+Math.random()*3});
  }
}
function score(side) {
  if (resetTimer > 0) return;
  if (side === 'you') { youScore++; goals++; showBanner('GOAL!  +1'); tone(780,.15,'triangle'); setTimeout(() => tone(980,.25,'triangle'),100); }
  else { aiScore++; showBanner('RIVAL SCORES'); tone(120,.3,'sawtooth',.025); }
  updateHud(); resetTimer = 1.6;
  for (let i = 0; i < 38; i++) {
    const a = Math.random() * Math.PI * 2, speed = 60 + Math.random() * 240;
    particles.push({x:ball.x,y:ball.y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:.55+Math.random()*.8,max:1.35,color:side === 'you' ? (Math.random()<.5?'#d8ff58':'#fff4c2') : (Math.random()<.5?'#ff705f':'#ffd0a1'),size:2+Math.random()*4});
  }
}
function movePlayer(actor, dx, dy, speed, dt) {
  if (dx || dy) {
    [dx, dy] = norm(dx, dy);
    actor.faceX = dx; actor.faceY = dy;
  }
  const targetX = dx * speed, targetY = dy * speed;
  const smoothing = Math.min(1, dt * 10);
  actor.vx += (targetX - actor.vx) * smoothing;
  actor.vy += (targetY - actor.vy) * smoothing;
  actor.x += actor.vx * dt; actor.y += actor.vy * dt;
  actor.x = clamp(actor.x, field.l + actor.r + 4, field.r - actor.r - 4);
  actor.y = clamp(actor.y, field.t + actor.r + 4, field.b - actor.r - 4);
}
function collidePlayerBall(actor, isRival = false) {
  let dx = ball.x - actor.x, dy = ball.y - actor.y;
  let d = Math.hypot(dx, dy) || 1;
  const min = actor.r + ball.r + 1;
  if (d < min) {
    const nx = dx / d, ny = dy / d;
    ball.x = actor.x + nx * min; ball.y = actor.y + ny * min;
    const approach = Math.max(0, actor.vx * nx + actor.vy * ny);
    ball.vx += nx * (38 + approach * .48) + actor.vx * .12;
    ball.vy += ny * (38 + approach * .48) + actor.vy * .12;
    if (isRival && rival.kickWait <= 0) shootRival();
  }
}
function tick(dt) {
  if (mode !== 'playing') return;
  if (!overtime) {
    matchTime -= dt;
    if (matchTime <= 0) {
      matchTime = 0;
      if (youScore === aiScore) { overtime = true; showBanner('GOLDEN GOAL'); tone(520,.32,'sine'); }
      else { updateHud(); showOverlay('finished'); return; }
    }
  }
  if (keys.has('Space')) charge = clamp((performance.now() - chargeAt) / 900, 0, 1);
  dashCooldown = Math.max(0, dashCooldown - dt);
  rival.kickWait = Math.max(0, rival.kickWait - dt);
  if (bannerTimer > 0) { bannerTimer -= dt; if (bannerTimer <= 0) $('banner').classList.remove('show'); }
  if (resetTimer > 0) {
    resetTimer -= dt;
    if (resetTimer <= 0) {
      if (overtime && youScore !== aiScore) { showOverlay('finished'); return; }
      resetPositions();
    }
  } else {
    const dx = (keys.has('ArrowRight') ? 1 : 0) - (keys.has('ArrowLeft') ? 1 : 0);
    const dy = (keys.has('ArrowDown') ? 1 : 0) - (keys.has('ArrowUp') ? 1 : 0);
    const sprinting = keys.has('ShiftLeft') || keys.has('ShiftRight');
    const speed = sprinting && dashCooldown <= 0 ? 310 : 232;
    if (sprinting && (dx || dy) && dashCooldown <= 0) { player.dash = .16; dashCooldown = .72; }
    player.dash = Math.max(0, player.dash - dt);
    movePlayer(player, dx, dy, speed, dt);

    let targetX = ball.x - 32, targetY = ball.y;
    if (ball.x < 500) { targetX = Math.max(610, ball.x + 82); targetY = 300 + (ball.y - 300) * .28; }
    else { targetX = ball.x + 8; targetY = ball.y + (ball.y > rival.y ? 12 : -12); }
    targetX = clamp(targetX, 570, 874); targetY = clamp(targetY, 95, 505);
    let ax = targetX - rival.x, ay = targetY - rival.y;
    const ad = Math.hypot(ax, ay);
    if (ad < 19 && ball.x < 500) { ax = ball.x - rival.x; ay = ball.y - rival.y; }
    const [anx, any] = norm(ax, ay);
    const botSpeed = ball.x > 810 ? 206 : 180;
    movePlayer(rival, ad < 20 ? anx : anx * Math.min(1, ad / 40), ad < 20 ? any : any * Math.min(1, ad / 40), botSpeed, dt);
    if (Math.hypot(ball.x-rival.x, ball.y-rival.y) < 52 && rival.kickWait <= 0 && ball.x < 820) shootRival();

    const pd = Math.hypot(player.x-rival.x, player.y-rival.y), pmin = player.r + rival.r;
    if (pd < pmin) { const nx = (rival.x-player.x)/(pd||1), ny = (rival.y-player.y)/(pd||1); player.x -= nx*2; player.y -= ny*2; rival.x += nx*2; rival.y += ny*2; }
    collidePlayerBall(player); collidePlayerBall(rival, true);
    ball.trail.unshift({x:ball.x,y:ball.y}); if (ball.trail.length > 7) ball.trail.pop();
    ball.x += ball.vx * dt; ball.y += ball.vy * dt;
    const friction = Math.pow(.987, dt * 60); ball.vx *= friction; ball.vy *= friction;
    ball.spin += Math.hypot(ball.vx, ball.vy) * dt * .008;
    const inGoalY = ball.y > goalTop && ball.y < goalBottom;
    if (ball.x < field.l && inGoalY) score('ai');
    else if (ball.x > field.r && inGoalY) score('you');
    else {
      if (ball.x < field.l + ball.r) { ball.x = field.l + ball.r; ball.vx = Math.abs(ball.vx) * .72; }
      if (ball.x > field.r - ball.r) { ball.x = field.r - ball.r; ball.vx = -Math.abs(ball.vx) * .72; }
      if (ball.y < field.t + ball.r) { ball.y = field.t + ball.r; ball.vy = Math.abs(ball.vy) * .72; }
      if (ball.y > field.b - ball.r) { ball.y = field.b - ball.r; ball.vy = -Math.abs(ball.vy) * .72; }
    }
    if (Math.hypot(ball.vx,ball.vy) < 4) ball.vx = ball.vy = 0;
  }
  particles = particles.filter(p => p.life > 0);
  for (const p of particles) { p.life -= dt; p.x += p.vx * dt; p.y += p.vy * dt; p.vx *= .985; p.vy = p.vy * .985 + 40 * dt; }
  updateHud();
}

